/* Enquêtes du volet « Le monde et la mondialisation » (un objet par chapitre, même index que v-mondial.js).
   P(titre, document(s), questions primaire, questions collège, indice). Q : la 1re réponse est la bonne. */
(function(){
'use strict';
var H=window.EQ;if(!H)return;
var Q=H.Q,V=H.V,O=H.O,T=H.T,R=H.R,W=H.W,I=H.I,X=H.X,M=H.M,TB=H.TB,F=H.F,P=H.P,E=function(ci,o){H.E('mondial',ci,o);};

E(0,{q:'Comment donner l’adresse exacte de la Nouvelle-Calédonie sur la planète ?',
h:['Avec sa latitude et sa longitude','Avec le nom de la plus grande ville du monde','C’est impossible : la Terre est ronde'],
pg:[
P('La Terre vue de l’espace',I('planisphere'),
 [Q('Combien y a-t-il de continents ?',['Six','Trois','Douze']),V('Les océans couvrent la plus grande partie de la Terre.',1)],
 [Q('Quelle part de la surface de la Terre est couverte par les océans ?',['Environ 71 %','Environ 10 %','Environ 50 %']),W('Pourquoi appelle-t-on la Terre la « planète bleue » ?','Parce qu’environ 71 % de sa surface est couverte d’océans : vue de l’espace, elle paraît surtout bleue.')],
 '71 % de la Terre est couverte d’océans ; les terres forment six continents.'),
P('Des lignes imaginaires',[M('Carte de l’atlas : équateur, tropiques, cercles polaires et méridien de Greenwich'),I('greenwich')],
 [Q('Quelle ligne sépare l’hémisphère Nord de l’hémisphère Sud ?',['L’équateur','Le tropique du Cancer','Le méridien de Greenwich']),R('Relie chaque ligne à ce qu’elle indique.',[['Équateur','Latitude 0°'],['Méridien de Greenwich','Longitude 0°'],['Tropiques','Limites de la zone chaude']])],
 [Q('Par où passe le méridien d’origine (longitude 0°) ?',['Par Greenwich, près de Londres','Par Nouméa','Par le sommet de l’Everest']),W('À quoi servent ces lignes, qu’on ne voit pas sur le sol ?','Ce sont des repères inventés par les humains : ils découpent la Terre en zones (chaude, tempérées, froides) et permettent de repérer n’importe quel lieu.')],
 'L’équateur (0° de latitude) et le méridien de Greenwich (0° de longitude) servent de point de départ.'),
P('Latitude et longitude',X('Fiche : l’adresse d’un lieu sur la Terre','Fiche de l’atlas.',"La latitude dit à quelle distance un lieu est de l'équateur, vers le nord (N) ou vers le sud (S). Elle va de 0° à l'équateur à 90° aux pôles.\nLa longitude dit à quelle distance un lieu est du méridien de Greenwich, vers l'est (E) ou vers l'ouest (O). Elle va de 0° à 180°.\nAvec les deux, on obtient l'adresse d'un lieu, comme sur une grille de bataille navale. Exemple : Nouméa est vers 22° S et 166° E.","Latitude : au nord ou au sud de l'équateur. Longitude : à l'est ou à l'ouest de Greenwich. Les deux ensemble donnent l'adresse d'un lieu, comme à la bataille navale."),
 [Q('À quel jeu ressemble ce système d’adresse ?',['À la bataille navale','Aux échecs','Au loto']),V('La latitude se compte depuis l’équateur.',1)],
 [T('La [latitude] se compte depuis l’équateur, la [longitude] depuis le méridien de Greenwich.',['altitude','température']),W('Pourquoi faut-il deux nombres pour donner l’adresse d’un lieu ?','Un seul nombre donne une ligne entière (tous les lieux à la même latitude) ; il faut croiser latitude et longitude pour obtenir un point précis.')],
 'Latitude (N/S depuis l’équateur) + longitude (E/O depuis Greenwich) = l’adresse d’un lieu.'),
P('Et nous ?',TB('Carte d’identité géographique de la Nouvelle-Calédonie',['Question','Réponse'],[['Hémisphère','Sud'],['Continent','Océanie'],['Océan','Pacifique, le plus grand océan du monde'],['Latitude','environ 21° S'],['Longitude','environ 165° E'],['Par rapport à la France','de l’autre côté de la Terre']],'Tableau de l’atlas.'),
 [Q('Dans quel océan est la Nouvelle-Calédonie ?',['L’océan Pacifique','L’océan Atlantique','L’océan Indien']),Q('Dans quel hémisphère est-elle ?',['L’hémisphère Sud','L’hémisphère Nord'])],
 [Q('Quelle est l’adresse approximative de la Nouvelle-Calédonie ?',['21° S, 165° E','21° N, 165° O','0°, 0°']),W('Pourquoi dit-on que la Nouvelle-Calédonie est « de l’autre côté de la Terre » par rapport à la France ?','La France est dans l’hémisphère Nord, en Europe, tout près du méridien de Greenwich ; la Nouvelle-Calédonie est dans l’hémisphère Sud, vers 165° de longitude est : presque à l’opposé sur le globe.')],
 'Nouvelle-Calédonie : hémisphère Sud, Océanie, Pacifique, vers 21° S et 165° E.')],
f:{p:'La Terre est couverte à 71 % par les [océans]. Pour trouver un lieu, on utilise sa [latitude], comptée depuis l’équateur, et sa [longitude], comptée depuis Greenwich. La Nouvelle-Calédonie est dans l’hémisphère [Sud].',w:['altitude','Nord','forêts'],
 c:['On croise sa latitude (environ 21° S, comptée depuis l’équateur) et sa longitude (environ 165° E, comptée depuis Greenwich) : c’est son adresse sur le globe.','On donne le nom de sa capitale, cela suffit.','On ne peut pas, car la Terre est ronde.'],
 r:'On utilise des lignes imaginaires : l’équateur sépare les hémisphères Nord et Sud et sert à compter la latitude ; le méridien de Greenwich sert à compter la longitude. En croisant les deux, on obtient l’adresse d’un lieu. La Nouvelle-Calédonie est vers 21° de latitude sud et 165° de longitude est : dans l’hémisphère Sud, en Océanie, dans le Pacifique, le plus grand océan du monde.'}});

E(1,{q:'Pourquoi les humains vivent-ils si souvent près des grands fleuves ?',
h:['Parce que les fleuves donnent de l’eau, des terres fertiles et une route','Parce qu’il fait plus froid près des fleuves','Parce que les montagnes sont interdites'],
pg:[
P('Le toit du monde',I('everest'),
 [Q('Quelle est la hauteur de l’Everest ?',['8 849 m','1 629 m','849 m']),V('L’Everest est dans l’Himalaya, en Asie.',1)],
 [Q('Combien de fois l’Everest est-il plus haut que le mont Panié (1 629 m) ?',['Environ 5 fois','Environ 2 fois','Environ 50 fois']),W('Pourquoi peu de gens vivent-ils en très haute montagne ?','Il y fait très froid, l’air manque d’oxygène, les pentes sont raides : il est difficile d’y cultiver, d’y construire et de s’y déplacer.')],
 'Les très hautes montagnes (Himalaya, Andes) sont peu peuplées : froid, pentes, air pauvre en oxygène.'),
P('Deux fleuves géants',[I('nil'),I('amazone')],
 [Q('Que voit-on le long du Nil, au milieu du désert ?',['Une bande verte de champs et de villes','De la neige','Une immense forêt']),V('Le Nil et l’Amazone mesurent plus de 6 000 km.',1)],
 [Q('Quel fleuve transporte le plus d’eau au monde ?',['L’Amazone','Le Nil','Le Mississippi']),W('Sur la photo du Nil vue de l’espace, qu’est-ce qui montre l’importance du fleuve ?','Le long du fleuve et dans son delta, une bande sombre et verte (champs, villes) traverse le désert jaune : sans le fleuve, il n’y aurait presque pas de vie.')],
 'Au milieu du désert, la vallée et le delta du Nil forment une bande verte et peuplée.'),
P('La carte des reliefs',M('Carte de l’atlas : les grands reliefs et les grands fleuves'),
 [R('Relie chaque montagne ou fleuve à son continent.',[['Himalaya','Asie'],['Andes','Amérique du Sud'],['Nil','Afrique']]),Q('Quelle est la plus longue chaîne de montagnes ?',['Les Andes','Les Alpes','La chaîne centrale calédonienne'])],
 [Q('Comment sont nées les montagnes « jeunes » comme l’Himalaya ?',['Quand des plaques de la Terre se sont rapprochées','Quand des fleuves ont creusé le sol','Quand des météorites sont tombées']),O('Classe ces sommets du plus haut au moins haut.',['Everest (8 849 m)','Aconcagua (6 961 m)','Kilimandjaro (5 895 m)','Mont Panié (1 629 m)'])],
 'Himalaya et Andes : montagnes jeunes, nées du rapprochement des plaques ; les grands fleuves traversent les plaines.'),
P('Des fleuves pour vivre',X('Fiche : ce que donne un grand fleuve','Fiche de l’atlas.',"L'eau : pour boire, se laver, arroser les champs.\nDes terres fertiles : quand le fleuve déborde, il dépose du limon, une boue très riche. Pendant des millénaires, les crues du Nil ont nourri l'Égypte.\nUne route : on transporte des marchandises en bateau, souvent moins cher que par la route.\nC'est pourquoi le delta du Nil ou la plaine du Gange comptent parmi les régions les plus peuplées du monde. En Nouvelle-Calédonie, l'île est étroite : les rivières sont courtes.","Un fleuve donne de l'eau, des terres fertiles (le limon) et une route pour les bateaux. C'est pour cela que beaucoup de gens vivent près des fleuves."),
 [Q('Comment s’appelle la boue fertile déposée par le fleuve ?',['Le limon','Le sable','La lave']),V('Les rivières calédoniennes sont courtes, car l’île est étroite.',1)],
 [Q('Quelle région est très peuplée grâce à son fleuve ?',['La plaine du Gange','Le Sahara','L’Antarctique']),W('Cite trois raisons pour lesquelles les humains s’installent près des fleuves.','L’eau (pour boire et irriguer), les terres fertiles déposées par les crues (le limon) et le transport des marchandises en bateau.')],
 'Un fleuve apporte de l’eau, du limon fertile et une route : ses rives attirent les humains.')],
f:{p:'Les très hautes [montagnes], comme l’Himalaya, sont peu peuplées. Au contraire, beaucoup d’humains vivent près des [fleuves] : ils donnent de l’[eau], des terres fertiles grâce au [limon] et une route pour les bateaux.',w:['déserts','neige','pétrole'],
 c:['Les fleuves apportent de l’eau, des terres fertiles (le limon) et une voie de transport : leurs vallées et leurs deltas, comme ceux du Nil ou du Gange, sont très peuplés.','Les fleuves sont toujours en haute montagne, là où tout le monde veut vivre.','Les humains évitent les fleuves à cause des crues.'],
 r:'Les hautes montagnes (Himalaya, Andes) sont peu peuplées : froid, pentes raides, air pauvre en oxygène. Les grands fleuves attirent au contraire les humains : ils donnent de l’eau pour boire et irriguer, des terres fertiles grâce au limon déposé par les crues, et une route pour transporter les marchandises. C’est pourquoi le delta du Nil, en plein désert, ou la plaine du Gange sont très peuplés.'}});

E(2,{q:'Pourquoi les paysages de la Terre sont-ils si différents d’une région à l’autre ?',
h:['Surtout à cause du climat : la chaleur et la pluie changent d’une région à l’autre','Parce que les humains ont planté toutes les forêts','Par hasard'],
pg:[
P('Trois grandes zones',M('Carte de l’atlas : zone chaude, zones tempérées et zones froides'),
 [Q('Où fait-il le plus chaud ?',['Près de l’équateur','Près des pôles','Partout pareil']),V('Plus on s’éloigne de l’équateur, plus il fait froid.',1)],
 [O('Range les zones de l’équateur vers le pôle.',['Zone chaude','Zone tempérée','Zone froide']),W('Pourquoi fait-il plus froid près des pôles ?','Les rayons du Soleil y arrivent très inclinés : la même énergie est étalée sur une plus grande surface, alors qu’à l’équateur ils arrivent presque à la verticale.')],
 'Zone chaude entre les tropiques, zones tempérées au milieu, zones froides près des pôles.'),
P('Chaud et humide, chaud et sec',[I('foretequat'),I('sahara2')],
 [R('Relie chaque milieu à son climat.',[['Forêt équatoriale','Chaud et pluvieux toute l’année'],['Désert','Il pleut très peu']]),Q('Où trouve-t-on de grandes forêts équatoriales ?',['En Amazonie, au Congo et en Indonésie','Au Sahara','En Antarctique'])],
 [Q('Pourquoi la forêt équatoriale est-elle si dense ?',['Il fait chaud et il pleut toute l’année','Il neige souvent','Les humains l’arrosent']),W('La forêt équatoriale et le désert sont tous deux dans la zone chaude. Qu’est-ce qui les rend si différents ?','La pluie : la forêt équatoriale reçoit de la pluie toute l’année, le désert presque jamais. La chaleur seule ne suffit pas à expliquer un milieu.')],
 'Même chaleur, pluie différente : forêt équatoriale (pluie toute l’année) ou désert (presque pas de pluie).'),
P('Le Grand Nord',I('taiga'),
 [Q('Quels arbres poussent dans la taïga ?',['Des conifères, comme les sapins','Des cocotiers','Des baobabs']),V('La taïga est une forêt des régions froides.',1)],
 [O('Range ces milieux du plus chaud au plus froid.',['Forêt équatoriale','Savane','Taïga','Banquise']),W('Comment le froid influence-t-il la vie des humains dans le Grand Nord ?','Les hivers sont longs et l’on peut peu cultiver : les habitants sont peu nombreux, doivent chauffer leurs maisons et vivent souvent de la forêt, de la pêche ou des mines.')],
 'Taïga, puis toundra et glace : plus on va vers le pôle, plus le milieu est froid.'),
P('Et chez nous ?',TB('Le climat de quelques lieux',['Lieu','Milieu','Climat'],[['Manaus (Amazonie, Brésil)','forêt équatoriale','chaud et pluvieux toute l’année'],['Tombouctou (Mali)','bord du Sahara','chaud, très peu de pluie'],['Nouméa (Nouvelle-Calédonie)','littoral tropical','chaud, avec une saison des pluies et une saison plus fraîche'],['Iakoutsk (Sibérie, Russie)','taïga','hiver très froid, été court']],'Tableau de l’atlas (descriptions simplifiées).'),
 [Q('Quel climat a la Nouvelle-Calédonie ?',['Un climat tropical','Un climat polaire','Un climat désertique']),Q('Où l’hiver est-il très froid ?',['À Iakoutsk, en Sibérie','À Manaus','À Nouméa'])],
 [Q('Dans quelle zone se trouve la Nouvelle-Calédonie ?',['Dans la zone chaude, près du tropique du Capricorne','Dans une zone froide','Exactement sur l’équateur']),W('Montre avec le tableau que le climat façonne les milieux.','À Manaus, la chaleur et la pluie toute l’année donnent la forêt équatoriale ; à Tombouctou, le manque de pluie donne le désert ; à Iakoutsk, le froid donne la taïga.')],
 'La Nouvelle-Calédonie a un climat tropical ; à chaque climat correspond un milieu.')],
f:{p:'Le [climat] change selon la latitude : il fait chaud près de l’[équateur] et froid près des [pôles]. Avec la chaleur et beaucoup de pluie pousse la [forêt] équatoriale ; avec très peu de pluie, c’est le désert.',w:['océan','tropiques','banquise'],
 c:['Le climat (températures et pluies), qui change surtout avec la latitude, façonne les milieux : forêt équatoriale, désert, savane, taïga, glace.','Tous les paysages ont été créés par les humains.','Les paysages sont répartis au hasard sur la planète.'],
 r:'Le climat explique la plupart des différences : plus on s’éloigne de l’équateur, plus il fait froid (zone chaude, zones tempérées, zones froides). La pluie compte aussi : dans la zone chaude, la forêt équatoriale reçoit de la pluie toute l’année alors que le désert n’en reçoit presque pas. Vers les pôles viennent la taïga, la toundra et la glace. La Nouvelle-Calédonie a un climat tropical.'}});

E(3,{q:'Où vivent les 8,2 milliards d’humains, et pourquoi pas ailleurs ?',
h:['Surtout en Asie, près des côtes, des fleuves et dans les plaines','Partout de la même façon','Surtout dans les déserts et en montagne'],
pg:[
P('La Terre, la nuit',I('nuitterre'),
 [Q('Que montrent les lumières sur cette image ?',['Les endroits où vivent beaucoup d’humains','Des volcans','Des étoiles']),V('Les lumières sont très nombreuses en Asie.',1)],
 [Q('Quel continent rassemble plus de la moitié des humains ?',['L’Asie','L’Europe','L’Océanie']),W('Pourquoi une image de la Terre la nuit est-elle utile pour étudier la population ? Quelle est sa limite ?','Les lumières des villes et des routes montrent où les humains sont nombreux ; les zones noires sont presque vides. Limite : les régions pauvres sont moins éclairées, l’image ne dit donc pas tout.')],
 'Les lumières montrent les foyers de peuplement ; plus de la moitié de l’humanité vit en Asie.'),
P('Foyers et déserts humains',[I('densite'),M('Carte de l’atlas : foyers de peuplement et déserts humains')],
 [Q('Lequel est un des grands foyers de peuplement ?',['L’Asie du Sud','Le Sahara','La Sibérie']),V('Le Sahara est presque vide d’habitants.',1)],
 [Q('Comment appelle-t-on une région presque vide d’habitants ?',['Un désert humain','Un foyer de peuplement','Une mégapole']),W('Explique pourquoi le Sahara, la Sibérie et l’Amazonie sont des « déserts humains ».','Ce sont des milieux aux fortes contraintes : trop sec (Sahara), trop froid (Sibérie), trop humide et couvert de forêt (Amazonie) ; il est difficile d’y cultiver et d’y vivre nombreux.')],
 'Trois grands foyers (Asie de l’Est, Asie du Sud, Europe) ; déserts humains : trop sec, trop froid, trop humide ou trop haut.'),
P('Serrés ou dispersés ?',[I('tokyo'),TB('Quelques densités de population (ordres de grandeur arrondis)',['Pays ou territoire','Habitants par km²'],[['Bangladesh','environ 1 300'],['France (métropole)','environ 120'],['Monde (moyenne)','environ 60'],['Nouvelle-Calédonie','environ 14'],['Australie','environ 3']],'Tableau de l’atlas, d’après l’ONU et les instituts de statistique.')],
 [Q('Quel pays du tableau est le plus densément peuplé ?',['Le Bangladesh','L’Australie','La Nouvelle-Calédonie']),V('La Nouvelle-Calédonie est moins densément peuplée que la France.',1)],
 [Q('L’Australie est immense mais très peu dense. Pourquoi ?',['Son intérieur est en grande partie désertique','Elle n’a pas de côtes','Il y fait trop froid']),W('Que signifie « densité de population » ? Calcule-la pour la Nouvelle-Calédonie (264 596 habitants, environ 18 600 km²).','C’est le nombre moyen d’habitants par km² : on divise la population par la superficie. 264 596 ÷ 18 600 ≈ 14 habitants par km².')],
 'Densité = habitants ÷ km² : Bangladesh ≈ 1 300, France ≈ 120, Nouvelle-Calédonie ≈ 14, Australie ≈ 3.'),
P('Près des côtes',X('Fiche : où les humains préfèrent-ils s’installer ?','Fiche de l’atlas.',"Beaucoup d'humains vivent près des côtes, des fleuves et dans les plaines : on peut y cultiver, commercer et se déplacer facilement.\nIls évitent les milieux trop secs, trop froids, trop humides ou trop montagneux.\nEn Nouvelle-Calédonie (264 596 habitants en 2025), c'est pareil : la population se concentre sur le littoral, surtout dans le Grand Nouméa, et l'intérieur de la chaîne est peu peuplé.","Les humains préfèrent les côtes, les fleuves et les plaines. En Nouvelle-Calédonie aussi : la plupart des gens vivent au bord de la mer, surtout autour de Nouméa."),
 [Q('Où vivent la plupart des Calédoniens ?',['Sur le littoral, surtout autour de Nouméa','Au sommet des montagnes','Sur des îlots inhabités']),V('Les humains évitent les milieux trop froids ou trop secs.',1)],
 [Q('Combien la Nouvelle-Calédonie compte-t-elle d’habitants (recensement 2025) ?',['264 596','2 645 960','26 459']),W('Compare la répartition de la population en Nouvelle-Calédonie et dans le monde.','Dans les deux cas, la population est très inégalement répartie : elle se concentre sur le littoral et dans les plaines, et évite les milieux difficiles (montagnes de la chaîne, déserts, grand froid).')],
 'Comme dans le monde, la population calédonienne se concentre sur le littoral.')],
f:{p:'En 2025, la Terre compte plus de 8,2 milliards d’[humains]. Plus de la moitié vit en [Asie]. Les humains s’installent surtout près des [côtes], des fleuves et dans les plaines, et évitent les milieux trop secs ou trop [froids].',w:['Océanie','montagnes','animaux'],
 c:['Ils vivent surtout dans quelques grands foyers (Asie de l’Est, Asie du Sud, Europe), près des côtes, des fleuves et dans les plaines ; les milieux trop secs, froids, humides ou montagneux restent presque vides.','Ils sont répartis de façon égale sur toutes les terres.','Ils vivent surtout dans les déserts, où il y a de la place.'],
 r:'Les 8,2 milliards d’humains sont très inégalement répartis. Plus de la moitié vit en Asie ; les trois grands foyers sont l’Asie de l’Est, l’Asie du Sud et l’Europe. Les humains préfèrent les côtes, les fleuves et les plaines, où l’on peut cultiver, commercer et se déplacer. Les milieux trop secs (Sahara), trop froids (Sibérie), trop humides (Amazonie) ou trop montagneux sont des déserts humains. La Nouvelle-Calédonie suit la même logique : sa population se concentre sur le littoral.'}});

E(4,{q:'Pourquoi les villes attirent-elles autant d’habitants, et à quel prix ?',
h:['Pour les emplois, les écoles et les hôpitaux, mais avec de la pollution et de la pauvreté','Parce que la vie y est gratuite','Parce que les campagnes ont disparu'],
pg:[
P('La plus grande ville du monde',I('jakarta'),
 [Q('Selon l’ONU (2025), quelle est la plus grande agglomération du monde ?',['Jakarta','Paris','Nouméa']),V('Neuf des dix plus grandes villes du monde sont en Asie.',1)],
 [Q('Comment appelle-t-on une ville de plus de 10 millions d’habitants ?',['Une mégapole','Une métropole régionale','Un village']),W('Jakarta compterait environ 42 millions d’habitants. Compare avec la Nouvelle-Calédonie (264 596).','Jakarta a environ 160 fois plus d’habitants que toute la Nouvelle-Calédonie : une seule agglomération peut être plus peuplée que bien des pays.')],
 'Jakarta (≈ 42 millions d’habitants) est la plus grande agglomération ; 9 des 10 plus grandes sont en Asie.'),
P('Le palmarès des géants',[TB('Les plus grandes agglomérations (ONU, 2025)',['Agglomération','Continent','Remarque'],[['Jakarta (Indonésie)','Asie','1re, environ 42 millions d’habitants'],['Dacca (Bangladesh)','Asie','2e, environ 37 à 40 millions'],['Tokyo (Japon)','Asie','3e, environ 33 millions'],['Le Caire (Égypte)','Afrique','la seule des dix premières hors d’Asie']],'Tableau de l’atlas, d’après l’ONU (2025).'),M('Carte de l’atlas : les grandes agglomérations du monde')],
 [Q('Sur quel continent se trouve Le Caire ?',['L’Afrique','L’Asie','L’Europe']),Q('Quelle ville est la troisième ?',['Tokyo','Jakarta','Lagos'])],
 [Q('Combien y a-t-il de mégapoles dans le monde (2025) ?',['33','3','330']),W('Où se trouvent beaucoup de mégapoles ? Pourquoi, d’après toi ?','Beaucoup sont au bord de la mer ou d’un grand fleuve : le port, le commerce, l’eau et les plaines facilitent la croissance d’une ville.')],
 'Les géants urbains sont surtout en Asie ; 33 mégapoles, souvent au bord de la mer ou d’un fleuve.'),
P('Ce qui attire en ville',X('Témoignage : Rina arrive à Jakarta','Personnage fictif. Situation inspirée de l’exode rural décrit par l’atlas.',"J'ai grandi dans un village de Java. Il y avait peu de travail, à part les rizières, et le collège était loin.\nÀ 19 ans, je suis partie à Jakarta. J'ai trouvé un emploi dans une usine de vêtements. Mon petit frère va au lycée ici, et ma mère a pu se faire soigner à l'hôpital.\nMais je passe deux heures par jour dans les embouteillages, et notre logement est minuscule.","Rina a quitté son village pour Jakarta : elle a trouvé du travail, son frère va au lycée, sa mère a été soignée. Mais il y a les embouteillages et un tout petit logement."),
 [Q('Pourquoi Rina est-elle partie en ville ?',['Pour trouver du travail','Pour faire du ski','Pour fuir la mer']),V('En ville, Rina passe beaucoup de temps dans les embouteillages.',1)],
 [Q('Comment appelle-t-on le départ des habitants des campagnes vers les villes ?',['L’exode rural','Le tourisme','La transhumance']),W('Classe ce que dit Rina en deux colonnes : ce qui attire en ville / les difficultés.','Ce qui attire : l’emploi en usine, le lycée pour son frère, l’hôpital pour sa mère. Les difficultés : deux heures d’embouteillages par jour, un logement minuscule.')],
 'Emplois, écoles et hôpitaux attirent en ville (exemple fictif de Rina), malgré les embouteillages.'),
P('L’autre visage de la ville',I('bidonville'),
 [Q('Comment appelle-t-on un quartier de maisons précaires, souvent sans eau courante ?',['Un bidonville','Un quartier d’affaires','Un lotissement']),V('Dans une même ville, il y a des quartiers riches et des quartiers pauvres.',1)],
 [Q('Où se trouve le bidonville de Kibera ?',['À Nairobi, au Kenya','À Paris','À Tokyo']),W('Pourquoi des bidonvilles se forment-ils dans les grandes villes ?','Les nouveaux habitants arrivent plus vite qu’on ne construit de logements ; les plus pauvres s’installent où ils peuvent, sans eau courante ni égouts.')],
 'La croissance rapide des villes crée aussi des bidonvilles, comme Kibera à Nairobi.')],
f:{p:'De plus en plus d’humains vivent en [ville]. Les plus grandes agglomérations sont en [Asie], comme [Jakarta]. Les villes attirent par leurs emplois, leurs écoles et leurs hôpitaux, mais on y trouve aussi des embouteillages, de la pollution et des [bidonvilles].',w:['Océanie','Nouméa','champs'],
 c:['Les villes offrent des emplois, des écoles et des hôpitaux ; elles grandissent très vite, surtout en Asie, mais avec des embouteillages, de la pollution et des bidonvilles.','Les villes attirent parce que tout y est gratuit et sans problème.','Les villes perdent des habitants partout dans le monde.'],
 r:'La part des citadins a plus que doublé depuis 1950 et l’on compte 33 mégapoles, surtout en Asie (Jakarta, Dacca, Tokyo). Les villes attirent les habitants des campagnes par leurs emplois, leurs écoles et leurs hôpitaux, comme le montre le témoignage (fictif) de Rina. Mais cette croissance rapide a un prix : embouteillages, pollution, logements trop petits et bidonvilles, comme Kibera à Nairobi.'}});

E(5,{q:'Comment les objets que nous achetons traversent-ils les océans, et que se passe-t-il si une route est bloquée ?',
h:['Ils voyagent surtout par la mer, en conteneurs ; si un passage est bloqué, le commerce mondial ralentit','Ils voyagent surtout en avion, et rien ne peut les bloquer','Ils sont tous fabriqués sur place'],
pg:[
P('La boîte qui a changé le monde',I('porteconteneurs'),
 [Q('Comment s’appelle la grande boîte en métal qui transporte les objets ?',['Un conteneur','Une pirogue','Un wagon']),V('Plus de 80 % des marchandises échangées voyagent par la mer.',1)],
 [Q('Combien de conteneurs les plus grands navires peuvent-ils porter ?',['Plus de 20 000','Environ 20','Environ 200']),W('Pourquoi le conteneur de taille standard a-t-il fait baisser le prix du transport ?','Toutes les boîtes ont la même taille : on les charge vite avec des grues, on les empile et on les passe du navire au camion ou au train sans les ouvrir. On gagne beaucoup de temps et d’argent.')],
 'Plus de 80 % des marchandises voyagent par la mer, dans des conteneurs de taille standard.'),
P('Raccourcis et passages',[M('Carte de l’atlas : les routes de la mer, détroits et canaux'),I('suez')],
 [R('Relie chaque canal à son année d’ouverture.',[['Canal de Suez','1869'],['Canal de Panama','1914']]),Q('Que relie le canal de Suez ?',['La mer Méditerranée et la mer Rouge','Le Pacifique et l’Atlantique','Nouméa et Lifou'])],
 [Q('Par quel détroit passe la grande route Asie – Europe ?',['Le détroit de Malacca','Le détroit de Béring','Le détroit de Gibraltar seulement']),W('Explique pourquoi les canaux de Suez et de Panama raccourcissent les trajets.','Sans eux, les navires devraient contourner l’Afrique ou l’Amérique du Sud ; les canaux coupent à travers la terre et font gagner des milliers de kilomètres.')],
 'Détroits (Malacca, Bab-el-Mandeb…) et canaux (Suez 1869, Panama 1914) raccourcissent les routes.'),
P('Mars 2021 : un géant en travers',X('Fiche : l’Ever Given bloque le canal de Suez','Fiche de l’atlas, d’après les faits de mars 2021.',"Le 23 mars 2021, par grand vent, un des plus grands porte-conteneurs du monde, l'Ever Given, se met en travers du canal de Suez.\nPendant six jours, plus aucun navire ne peut passer. Des centaines de bateaux attendent aux deux entrées du canal ; certains préfèrent faire le tour de l'Afrique.\nEn Europe, des usines et des magasins attendent des pièces et des marchandises qui arrivent en retard.","En mars 2021, un énorme bateau, l'Ever Given, bloque le canal de Suez pendant six jours. Des centaines de navires attendent : en Europe, des marchandises arrivent en retard."),
 [Q('Combien de jours le canal a-t-il été bloqué ?',['Six jours','Six heures','Six mois']),V('Certains bateaux ont préféré faire le tour de l’Afrique.',1)],
 [O('Remets les événements dans l’ordre.',['Le navire se met en travers du canal','Plus aucun bateau ne peut passer','Des centaines de navires attendent','Des usines d’Europe manquent de pièces']),W('Pourquoi un seul bateau bloqué en Égypte peut-il gêner des usines en Europe ?','Une grande partie du commerce entre l’Asie et l’Europe passe par Suez : si le canal est fermé, les pièces arrivent en retard et les usines, qui dépendent de ces livraisons, ralentissent.')],
 'En 2021, l’Ever Given bloque Suez six jours : le commerce entre l’Asie et l’Europe est ralenti.'),
P('Les ports géants',[I('shanghaiport'),TB('Les plus grands ports à conteneurs',['Port','Pays','Rang'],[['Shanghai','Chine','1er du monde'],['Singapour','Singapour','2e'],['Ningbo','Chine','3e'],['Rotterdam','Pays-Bas','1er d’Europe']],'Tableau de l’atlas.')],
 [Q('Quel est le premier port à conteneurs du monde ?',['Shanghai','Rotterdam','Nouméa']),Q('Dans quel pays sont la plupart des très grands ports ?',['En Chine','En France','En Australie'])],
 [Q('Comment les conteneurs arrivent-ils souvent à Nouméa ?',['Après un transbordement dans un grand port, comme Singapour','Directement depuis chaque usine','Uniquement par avion']),W('Pourquoi les plus grands ports du monde sont-ils en Chine ?','La Chine fabrique et exporte une énorme quantité de marchandises vers le monde entier : il lui faut des ports géants pour les charger.')],
 'Shanghai, Singapour, Ningbo : les géants sont en Asie ; Nouméa reçoit des conteneurs après transbordement.')],
f:{p:'Plus de 80 % des marchandises voyagent par la [mer], dans des [conteneurs]. Les canaux comme celui de [Suez] raccourcissent les trajets. En 2021, un navire bloqué a ralenti le [commerce] mondial.',w:['avion','camions','Panama'],
 c:['Les marchandises voyagent surtout par la mer, en conteneurs, sur de grandes routes qui passent par des détroits et des canaux ; si l’un d’eux est bloqué, comme Suez en 2021, le commerce mondial ralentit.','Elles voyagent surtout en avion ; les canaux ne servent plus.','Tous les objets sont fabriqués dans le pays où on les achète.'],
 r:'Plus de 80 % des marchandises échangées voyagent par la mer, dans des conteneurs de taille standard portés par des navires géants (plus de 20 000 conteneurs). Les routes passent par des détroits (Malacca) et des canaux (Suez, Panama) qui raccourcissent les trajets. Ce sont des points fragiles : en mars 2021, l’Ever Given a bloqué Suez pendant six jours et des centaines de navires ont attendu. Les plus grands ports sont en Chine ; les conteneurs arrivent à Nouméa après un transbordement.'}});

E(6,{q:'Par où passe internet entre les continents, et pourquoi la Nouvelle-Calédonie a-t-elle voulu un deuxième câble ?',
h:['Par des câbles posés au fond de la mer ; un deuxième câble évite d’être coupé du monde','Par les nuages','Uniquement par les satellites'],
pg:[
P('Un câble, c’est quoi ?',I('cablesous'),
 [Q('Que transportent les fibres optiques ?',['De la lumière','De l’eau','Du pétrole']),V('Presque tout internet entre les continents passe par des câbles sous la mer.',1)],
 [Q('Une fibre optique est fine comme…',['un cheveu','un tronc d’arbre','un tuyau d’arrosage']),W('Beaucoup de gens pensent qu’internet passe par les satellites. Que montre ce document ?','Presque toutes les données entre continents passent par des câbles posés au fond des océans ; ils contiennent des fibres optiques qui transportent l’information sous forme de lumière.')],
 'Internet passe sous la mer, dans des câbles à fibres optiques.'),
P('Poser les câbles',[I('cablenavire'),M('Carte de l’atlas : les grands câbles sous-marins')],
 [Q('Quel bateau pose les câbles ?',['Un navire câblier','Un porte-avions','Une pirogue']),Q('Quelles régions sont les mieux reliées ?',['L’Amérique du Nord, l’Europe et l’Asie','Les petites îles du Pacifique','L’Antarctique'])],
 [Q('Quel risque court une petite île reliée par un seul câble ?',['Être coupée d’internet si le câble casse','Être inondée par le câble','N’avoir plus d’électricité']),W('Compare sur la carte les grandes routes de câbles et les petites îles.','Les grandes routes relient l’Amérique du Nord, l’Europe et l’Asie ; beaucoup de petites îles n’ont qu’un seul câble : elles sont moins bien reliées et plus fragiles.')],
 'Les câbles relient surtout l’Amérique du Nord, l’Europe et l’Asie ; beaucoup de petites îles n’ont qu’un câble.'),
P('Là où vivent les données',I('datacenter'),
 [Q('Que trouve-t-on dans un centre de données ?',['Des milliers d’ordinateurs','Des vaches','Seulement des livres']),V('Les vidéos et les sites sont stockés dans des centres de données.',1)],
 [Q('Où se trouvent surtout les centres de données ?',['En Amérique du Nord, en Europe et en Asie','En Antarctique','Sur les atolls']),W('Pourquoi peut-on dire qu’internet n’est pas « dans les nuages » mais bien sur Terre ?','Les données sont stockées dans d’immenses bâtiments remplis d’ordinateurs, qui consomment beaucoup d’électricité, et elles voyagent dans de vrais câbles au fond de la mer.')],
 'Les données sont stockées dans des centres de données, de vrais bâtiments sur Terre.'),
P('Et chez nous ?',F('Internet arrive en Nouvelle-Calédonie',[['Avant 2008','Internet passe par satellite : c’est lent et cher.'],['2008','Le câble Gondwana-1 relie la Nouvelle-Calédonie à Sydney (Australie).'],['2022','Le câble Gondwana-2 relie la Nouvelle-Calédonie à Fidji.'],['Aujourd’hui','Avec deux câbles, si l’un est coupé, l’autre prend le relais.']]),
 [Q('Vers quelle ville va le câble Gondwana-1 ?',['Sydney','Paris','Tokyo']),O('Remets dans l’ordre.',['Internet par satellite','Gondwana-1 vers Sydney','Gondwana-2 vers Fidji'])],
 [Q('En quelle année Gondwana-2 a-t-il été mis en service ?',['2022','2008','1990']),W('Pourquoi un deuxième câble était-il important pour la Nouvelle-Calédonie ?','Avec un seul câble, une coupure (une ancre, un séisme) privait tout le pays d’internet. Avec Gondwana-1 et Gondwana-2, si l’un casse, l’autre prend le relais.')],
 'Gondwana-1 (2008, Sydney) et Gondwana-2 (2022, Fidji) : avec deux câbles, le pays n’est plus coupé du monde si l’un casse.')],
f:{p:'Internet passe surtout par des [câbles] posés au fond de la mer. Ils contiennent des fibres optiques qui transportent la [lumière]. La Nouvelle-Calédonie est reliée à Sydney par Gondwana-1 et à [Fidji] par Gondwana-2 : avec deux câbles, elle n’est plus [coupée] du monde si l’un casse.',w:['satellites','Tahiti','électricité'],
 c:['Internet passe entre les continents par des câbles sous-marins à fibres optiques ; avec Gondwana-1 (Sydney) et Gondwana-2 (Fidji), la Nouvelle-Calédonie reste reliée même si un câble est coupé.','Internet passe uniquement par les satellites : les câbles ne servent à rien.','La Nouvelle-Calédonie n’est reliée à aucun câble.'],
 r:'Presque toutes les données entre continents passent par des câbles posés au fond des océans, remplis de fibres optiques qui transportent la lumière ; des navires câbliers les déroulent. Les données sont stockées dans des centres de données, surtout en Amérique du Nord, en Europe et en Asie. Les petites îles, souvent reliées par un seul câble, sont fragiles. La Nouvelle-Calédonie a Gondwana-1 (2008, vers Sydney) et Gondwana-2 (2022, vers Fidji) : si l’un casse, l’autre prend le relais.'}});

E(7,{q:'Pourquoi les humains se déplacent-ils autant aujourd’hui, et sont-ils tous aussi libres de voyager ?',
h:['Pour le tourisme, le travail, les études ou pour fuir un danger ; mais tous n’ont pas la même liberté','Uniquement pour les vacances','Ils se déplacent moins qu’autrefois'],
pg:[
P('Les carrefours du ciel',[I('aeroportdubai'),M('Carte de l’atlas : grands aéroports et migrations')],
 [Q('Combien de temps faut-il pour faire le tour de la Terre en avion ?',['Moins de deux jours','Un an','Trois mois']),Q('Lequel est un grand aéroport « carrefour » ?',['Dubaï','Pouembout','Ouvéa'])],
 [Q('Comment appelle-t-on un aéroport carrefour qui relie de nombreuses lignes ?',['Un hub','Un wharf','Une gare routière']),W('Pourquoi des villes comme Dubaï ou Singapour sont-elles devenues des carrefours aériens ?','Elles sont placées entre plusieurs continents (Europe, Asie, Afrique, Océanie) : les avions y font escale et les passagers y changent d’avion.')],
 'Des hubs (Dubaï, Singapour, Londres, Atlanta) relient tous les continents.'),
P('Touristes et migrants',TB('Voyager dans le monde : quelques chiffres',['Qui ?','Combien ?','Pourquoi ?'],[['Touristes internationaux','environ 1,4 milliard d’arrivées en 2024','vacances, découverte, visite à la famille'],['Migrants','environ 300 millions de personnes vivent hors de leur pays de naissance','travail, études, famille, fuir une guerre ou une catastrophe'],['Réfugiés','une partie des migrants','fuir une guerre ou des persécutions']],'Tableau de l’atlas, d’après l’ONU (chiffres arrondis).'),
 [Q('Combien y a-t-il eu d’arrivées de touristes internationaux en 2024 ?',['Environ 1,4 milliard','Environ 1 400','Environ 14']),V('Certaines personnes quittent leur pays pour fuir une guerre.',1)],
 [Q('Quelle est la différence entre un touriste et un migrant ?',['Le touriste voyage pour peu de temps ; le migrant s’installe dans un autre pays','Il n’y a aucune différence','Le migrant ne voyage jamais']),W('Cite trois raisons pour lesquelles une personne peut migrer.','Pour travailler, étudier, rejoindre sa famille, fuir une guerre, des persécutions ou une catastrophe.')],
 'Environ 1,4 milliard d’arrivées de touristes (2024) et environ 300 millions de migrants dans le monde.'),
P('Dans le Pacifique',X('Témoignage : Sione, entre Wallis et Nouméa','Personnage fictif. Situation inspirée des migrations décrites par l’atlas.',"Mes grands-parents sont arrivés de Wallis dans les années 1960, pour travailler pendant le boom du nickel. Mon père est né à Nouméa, moi aussi.\nL'été dernier, je suis allé à Wallis pour la première fois, voir la famille. Mon cousin, lui, est parti étudier en Nouvelle-Zélande.\nAujourd'hui, il y a plus de Wallisiens et de Futuniens en Nouvelle-Calédonie qu'à Wallis-et-Futuna.","Les grands-parents de Sione sont venus de Wallis pour travailler. Sione est né à Nouméa. Son cousin étudie en Nouvelle-Zélande. Il y a plus de Wallisiens en Nouvelle-Calédonie qu'à Wallis-et-Futuna."),
 [Q('Pourquoi les grands-parents de Sione sont-ils venus en Nouvelle-Calédonie ?',['Pour travailler','Pour faire du tourisme','Pour fuir la neige']),V('Il y a plus de Wallisiens et de Futuniens en Nouvelle-Calédonie qu’à Wallis-et-Futuna.',1)],
 [Q('Vers quels pays partent aussi beaucoup d’Océaniens ?',['La Nouvelle-Zélande et l’Australie','Le Canada et la Russie','Le Brésil et l’Argentine']),W('Ce témoignage est inventé. Quels faits réels y retrouve-t-on ?','L’arrivée de travailleurs wallisiens pendant le boom du nickel, le fait qu’ils soient plus nombreux en Nouvelle-Calédonie qu’à Wallis-et-Futuna, et les départs d’Océaniens vers la Nouvelle-Zélande pour étudier ou travailler.')],
 'Les migrations relient aussi les îles : Wallis → Nouvelle-Calédonie, Océanie → Nouvelle-Zélande et Australie.'),
P('Partir de chez nous',I('aircalin'),
 [Q('Quelle est la compagnie aérienne de la Nouvelle-Calédonie ?',['Aircalin','Air Lune','Pirogue Express']),V('Pour quitter la Nouvelle-Calédonie, on prend presque toujours l’avion.',1)],
 [Q('Par quel aéroport international partent les avions de Nouvelle-Calédonie ?',['La Tontouta','Koné','Lifou-Wanaham']),W('« Tous n’ont pas la même liberté de circuler. » Explique cette phrase.','Selon son passeport, son argent ou la situation de son pays, on voyage facilement ou non : certains ont besoin de visas difficiles à obtenir, d’autres ne peuvent pas payer le billet, d’autres sont bloqués par une guerre.')],
 'Aircalin et La Tontouta relient la Nouvelle-Calédonie au monde ; mais tous n’ont pas la même liberté de voyager.')],
f:{p:'Grâce à l’[avion], on fait le tour de la Terre en moins de deux jours. En 2024, il y a eu 1,4 milliard d’arrivées de [touristes]. Environ 300 millions de [migrants] vivent hors de leur pays de naissance. Mais tous n’ont pas la même [liberté] de voyager.',w:['pirogue','soldats','obligation'],
 c:['Avions et grands aéroports rendent les voyages faciles : touristes, étudiants, travailleurs et réfugiés se déplacent comme jamais, mais tous n’ont pas la même liberté de circuler.','Seuls les touristes voyagent ; plus personne ne migre aujourd’hui.','Tout le monde peut aller partout sans aucune limite.'],
 r:'Les hubs aériens (Dubaï, Singapour…) relient tous les continents : on fait le tour de la Terre en moins de deux jours. En 2024, il y a eu environ 1,4 milliard d’arrivées de touristes internationaux, et environ 300 millions de personnes vivent hors de leur pays de naissance, pour travailler, étudier ou fuir une guerre ou une catastrophe. Le Pacifique aussi bouge : il y a plus de Wallisiens en Nouvelle-Calédonie qu’à Wallis-et-Futuna. Mais selon le pays, le passeport ou l’argent, tous n’ont pas la même liberté de circuler.'}});

E(8,{q:'Comment un téléphone fait-il le tour du monde avant d’arriver dans ta poche ?',
h:['Ses métaux, ses pièces et son assemblage viennent de nombreux pays différents','Il est entièrement fabriqué dans le magasin où on l’achète','Il est fabriqué en Nouvelle-Calédonie'],
pg:[
P('Un téléphone démonté',I('smartphone'),
 [Q('Combien de pays participent à la fabrication d’un téléphone ?',['Beaucoup de pays','Un seul pays','Aucun pays']),V('Un téléphone contient des métaux venus du monde entier.',1)],
 [Q('Comment appelle-t-on une entreprise installée dans de nombreux pays ?',['Une firme transnationale','Une coopérative de village','Une association de quartier']),W('Pourquoi un téléphone est-il un bon exemple de mondialisation ?','Il est conçu dans un pays, fabriqué avec des métaux et des pièces venus de nombreux pays, assemblé dans un autre et vendu partout : toutes ces régions du monde sont reliées.')],
 'Le téléphone est conçu, fabriqué et vendu par des firmes transnationales, avec des pièces du monde entier.'),
P('Des métaux du monde entier',[I('cobalt'),I('lithium')],
 [R('Relie chaque métal au pays qui en produit beaucoup.',[['Cobalt','République démocratique du Congo'],['Lithium','Chili et Australie'],['Terres rares','Chine']]),V('La batterie du téléphone contient du lithium.',1)],
 [Q('Quelle part du cobalt mondial vient de RD Congo ?',['Plus des deux tiers','Un centième','Aucune']),W('Pourquoi les mines de cobalt ou de lithium posent-elles des questions ?','Les conditions de travail dans certaines mines sont très dures, et l’extraction abîme l’environnement (eau, sols, paysages) ; nous profitons des téléphones loin de ces problèmes.')],
 'Cobalt (RD Congo, plus des deux tiers), lithium (Chili, Australie), terres rares (Chine).'),
P('La chaîne de fabrication',M('Carte de l’atlas : le voyage d’un téléphone'),
 [O('Remets les étapes dans l’ordre.',['Conception en Californie ou en Corée','Extraction des métaux','Assemblage en Chine, en Inde ou au Vietnam','Vente partout, jusqu’à Nouméa']),Q('Où sont fabriquées les puces les plus fines ?',['À Taïwan','En Antarctique','À Lifou'])],
 [R('Relie chaque étape à un lieu.',[['Puces les plus fines','Taïwan'],['Écrans','Corée du Sud'],['Assemblage','Chine, Inde ou Vietnam']]),W('Pourquoi chaque étape se fait-elle dans un pays différent ?','Chaque étape se fait là où c’est le moins cher ou le plus efficace : savoir-faire (les puces à Taïwan), métaux dans le sous-sol, main-d’œuvre moins chère pour l’assemblage.')],
 'Conception → métaux → pièces (Taïwan, Corée du Sud) → assemblage (Chine, Inde, Vietnam) → vente partout.'),
P('Et après ?',X('Fiche : que faire d’un vieux téléphone ?','Fiche de l’atlas.',"Un vieux téléphone contient des métaux précieux : un peu d'or, d'argent, de cuivre, de cobalt.\nSi on le jette à la poubelle, ces métaux sont perdus et les produits de la batterie peuvent polluer.\nSi on le rapporte dans un point de collecte, on peut récupérer une partie des métaux : il faudra creuser moins de nouvelles mines.\nGarder son téléphone plus longtemps, le faire réparer, c'est aussi l'un des meilleurs gestes.","Un vieux téléphone contient des métaux précieux. À la poubelle, ils sont perdus et la batterie peut polluer. Dans un point de collecte, on les récupère. Le garder longtemps, c'est encore mieux."),
 [Q('Où faut-il rapporter un vieux téléphone ?',['Dans un point de collecte','Dans la mer','Dans la poubelle de la cuisine']),V('Garder son téléphone plus longtemps est un bon geste.',1)],
 [Q('Pourquoi recycler les téléphones aide-t-il l’environnement ?',['On récupère des métaux et on creuse moins de mines','Cela fabrique de l’électricité','Cela fait pousser des arbres']),W('Propose deux gestes pour limiter les effets de nos téléphones sur la planète.','Garder son téléphone plus longtemps (le faire réparer), le rapporter dans un point de collecte pour récupérer les métaux, ne pas en racheter un sans en avoir besoin.')],
 'Recycler et garder longtemps son téléphone : moins de mines, moins de pollution.')],
f:{p:'Un téléphone est conçu par une [firme] transnationale. Sa batterie contient du [cobalt] et du lithium venus d’autres continents. Il est [assemblé] en Asie puis vendu partout. C’est un exemple de [mondialisation].',w:['coopérative','pétrole','planté'],
 c:['Il est conçu dans un pays, fabriqué avec des métaux (cobalt du Congo, lithium du Chili ou d’Australie) et des pièces d’Asie (Taïwan, Corée du Sud), assemblé en Chine, en Inde ou au Vietnam, puis expédié partout : c’est une chaîne mondiale.','Il est fabriqué entièrement par le magasin qui le vend.','Il est fabriqué en Nouvelle-Calédonie, avec du nickel uniquement.'],
 r:'Le téléphone est conçu en Californie, en Corée du Sud ou en Chine par une firme transnationale. Ses métaux viennent de plusieurs continents : cobalt de RD Congo (plus des deux tiers), lithium du Chili et d’Australie, terres rares de Chine. Les puces sont fabriquées à Taïwan, les écrans en Corée du Sud ; l’assemblage a lieu en Chine, en Inde ou au Vietnam. Il est ensuite expédié par avion ou par porte-conteneurs jusqu’à Nouméa. Chaque étape se fait là où c’est le moins cher ou le plus efficace : c’est la mondialisation, avec ses questions sur le travail et l’environnement.'}});

E(9,{q:'Comment mesurer les inégalités de développement dans le monde ?',
h:['Avec un indice qui combine la santé, l’éducation et le niveau de vie (l’IDH)','En comptant seulement le nombre de voitures','On ne peut pas les mesurer'],
pg:[
P('Une carte en couleurs',[I('idh'),M('Carte de l’atlas : un monde inégal')],
 [Q('Que mesure l’IDH ?',['Le développement humain','La hauteur des montagnes','La température']),Q('Où se trouvent surtout les pays les moins développés ?',['En Afrique subsaharienne','En Europe du Nord','En Australie'])],
 [R('Relie chaque partie de l’IDH à ce qu’on mesure.',[['Santé','Espérance de vie'],['Éducation','Années d’école'],['Niveau de vie','Revenu']]),W('Décris la répartition des pays les plus et les moins développés.','Les plus développés sont surtout en Europe du Nord, en Amérique du Nord, au Japon et en Australie ; les moins développés surtout en Afrique subsaharienne, notamment au Sahel.')],
 'IDH = santé + éducation + niveau de vie ; en bas du classement, surtout l’Afrique subsaharienne.'),
P('Deux pays, deux vies',TB('Comparer deux pays (ordres de grandeur arrondis)',['Indicateur','Suisse (Europe)','Niger (Sahel)'],[['Espérance de vie à la naissance','plus de 80 ans','environ 60 ans'],['Durée moyenne de scolarité des adultes','plus de 13 ans','moins de 3 ans'],['Niveau de vie','parmi les plus élevés du monde','parmi les plus faibles du monde'],['Classement IDH','dans les tout premiers','dans les tout derniers']],'Tableau de l’atlas, d’après le Programme des Nations unies pour le développement.'),
 [Q('Dans quel pays vit-on le plus longtemps ?',['En Suisse','Au Niger']),V('Au Niger, beaucoup d’adultes sont allés très peu de temps à l’école.',1)],
 [Q('Combien d’années d’espérance de vie séparent environ ces deux pays ?',['Environ 20 ans','Environ 2 ans','Environ 60 ans']),W('Pourquoi l’IDH utilise-t-il trois critères plutôt qu’un seul ?','Un seul chiffre, comme le revenu, ne dit pas tout : un pays peut être riche mais mal soigner ou mal scolariser ses habitants. Combiner santé, éducation et niveau de vie donne une image plus juste.')],
 'Suisse et Niger : environ 20 ans d’écart d’espérance de vie et des écarts énormes de scolarité.'),
P('Aller à l’école',I('ecole_afrique'),
 [Q('Que voit-on sur la photo ?',['Une école en Afrique','Un aéroport','Une usine']),V('L’éducation fait partie de l’IDH.',1)],
 [Q('Qu’est-ce qui peut empêcher des enfants d’aller à l’école ?',['La pauvreté, la guerre ou l’éloignement','Une pluie fine','Les vacances']),W('Pourquoi construire des écoles aide-t-il un pays à se développer ?','Des enfants instruits trouveront de meilleurs emplois, soigneront mieux leur famille et feront progresser leur pays : l’éducation améliore aussi la santé et le niveau de vie.')],
 'Écoles, centres de santé, eau potable, électricité : des actions pour réduire les inégalités.'),
P('Des inégalités partout',[I('bidonville'),X('Fiche : et la Nouvelle-Calédonie ?','Fiche de l’atlas.',"Le niveau de vie moyen de la Nouvelle-Calédonie est élevé pour le Pacifique.\nMais une moyenne cache des écarts : les inégalités entre habitants et entre provinces restent fortes. Certains quartiers et certaines communes sont mieux équipés que d'autres.\nC'est vrai dans presque tous les pays : il y a des quartiers riches et des bidonvilles, des villes équipées et des campagnes isolées.","La Nouvelle-Calédonie a un bon niveau de vie moyen pour le Pacifique, mais les écarts entre habitants et entre provinces restent forts.")],
 [V('Il y a des inégalités même à l’intérieur d’un pays.',1),Q('Pour le Pacifique, le niveau de vie moyen de la Nouvelle-Calédonie est…',['élevé','le plus bas du monde','le plus élevé du monde'])],
 [Q('Pourquoi une moyenne peut-elle tromper ?',['Elle cache les écarts entre les plus riches et les plus pauvres','Elle est toujours fausse','Elle ne compte que les enfants']),W('Donne deux exemples d’inégalités à l’intérieur d’un même pays.','Dans une même ville, un quartier riche à côté d’un bidonville (Kibera à Nairobi) ; des écarts entre villes équipées et campagnes isolées ; en Nouvelle-Calédonie, des écarts entre habitants et entre provinces.')],
 'Une moyenne élevée cache des écarts : entre habitants, entre quartiers, entre provinces.')],
f:{p:'Pour mesurer le développement, on utilise l’[IDH]. Il combine la [santé], l’éducation et le niveau de vie. Les pays les moins développés sont surtout en [Afrique] subsaharienne. Mais il y a aussi des [inégalités] à l’intérieur de chaque pays.',w:['météo','Europe','montagnes'],
 c:['Avec l’IDH, qui combine santé (espérance de vie), éducation (années d’école) et niveau de vie (revenu) ; il montre de grands écarts entre pays, et il existe aussi des inégalités à l’intérieur de chaque pays.','En comptant le nombre de voitures de chaque pays.','Les inégalités ne se mesurent pas : tous les pays se ressemblent.'],
 r:'On utilise l’indice de développement humain (IDH), qui combine la santé (espérance de vie), l’éducation (années d’école) et le niveau de vie (revenu). Les pays d’Europe du Nord, la Suisse, le Japon ou l’Australie sont en tête ; ceux d’Afrique subsaharienne, comme au Sahel, en bas : environ 20 ans d’espérance de vie séparent la Suisse et le Niger. Mais il y a aussi des inégalités à l’intérieur des pays : quartiers riches et bidonvilles, villes et campagnes isolées, et en Nouvelle-Calédonie entre habitants et entre provinces.'}});

E(10,{q:'Pourquoi les îles du Pacifique sont-elles en première ligne face au changement climatique ?',
h:['Parce que la mer monte et que beaucoup d’îles, surtout les atolls, sont très basses','Parce qu’elles polluent plus que tous les autres pays','Parce qu’il y fait trop froid'],
pg:[
P('La Terre se réchauffe',X('Fiche : l’effet de serre','Fiche de l’atlas.',"Certains gaz de l'air, comme le gaz carbonique, retiennent la chaleur du Soleil autour de la Terre, comme les vitres d'une serre : c'est l'effet de serre. Sans lui, il ferait trop froid pour vivre.\nMais en brûlant du charbon, du pétrole et du gaz, les humains ajoutent beaucoup de ces gaz. La chaleur est davantage retenue : la planète se réchauffe.\nLes glaciers et les glaces des pôles fondent.","Des gaz retiennent la chaleur autour de la Terre, comme une serre. En brûlant du charbon, du pétrole et du gaz, on en ajoute trop : la Terre se réchauffe et les glaces fondent."),
 [Q('Que brûlent les humains, ce qui réchauffe la planète ?',['Du charbon, du pétrole et du gaz','Seulement du bois de santal','De l’eau']),V('Sans effet de serre, il ferait trop froid pour vivre sur Terre.',1)],
 [Q('À quoi compare-t-on les gaz à effet de serre ?',['Aux vitres d’une serre','À un parapluie','À un aspirateur']),W('L’effet de serre est naturel et utile. Pourquoi pose-t-il problème aujourd’hui ?','Les humains rejettent beaucoup de gaz à effet de serre en brûlant charbon, pétrole et gaz : la chaleur est davantage retenue et la planète se réchauffe trop vite.')],
 'Charbon, pétrole et gaz renforcent l’effet de serre : la Terre se réchauffe, les glaces fondent.'),
P('La mer monte',[M('Carte de l’atlas : le Pacifique face au changement climatique'),TB('Pourquoi la mer monte',['Cause','Explication'],[['L’eau chauffe','En chauffant, l’eau des océans se dilate : elle prend plus de place.'],['Les glaces fondent','L’eau des glaciers et des calottes polaires arrive dans l’océan.'],['Résultat','Le niveau de la mer est monté d’environ 20 cm depuis 1900.']],'Tableau de l’atlas.')],
 [Q('De combien la mer est-elle montée depuis 1900 ?',['Environ 20 cm','Environ 20 m','Environ 2 km']),V('Quand l’eau chauffe, elle prend plus de place.',1)],
 [Q('Quelles côtes sont les plus menacées ?',['Les côtes basses et les atolls','Les très hautes falaises','Les montagnes']),W('Explique les deux raisons pour lesquelles le niveau de la mer monte.','L’eau des océans se dilate en se réchauffant, et la fonte des glaciers et des calottes polaires ajoute de l’eau dans l’océan.')],
 'La mer monte (environ 20 cm depuis 1900) : l’eau se dilate et les glaces fondent.'),
P('Tuvalu, un pays à fleur d’eau',I('funafuti'),
 [Q('Comment appelle-t-on une île basse en forme d’anneau de corail ?',['Un atoll','Un volcan','Une presqu’île']),V('Tuvalu dépasse à peine le niveau de la mer.',1)],
 [Q('Que prévoit le traité signé en 2023 entre Tuvalu et l’Australie ?',['Chaque année, jusqu’à 280 Tuvaluans peuvent s’installer en Australie','Tuvalu devient une province australienne','Tous les Tuvaluans doivent partir en 2024']),W('Pourquoi ce traité montre-t-il que la montée de la mer est prise au sérieux ?','Un pays prépare déjà le départ possible d’une partie de ses habitants : la menace sur les atolls n’est plus lointaine, elle change déjà la vie et les lois.')],
 'Tuvalu (environ 11 000 habitants) : des atolls très bas ; traité de 2023 avec l’Australie (280 personnes par an).'),
P('Coraux et solutions',[I('blanchiment'),F('Agir à deux échelles',[['2015','Accord de Paris : presque tous les pays s’engagent à limiter le réchauffement.'],['Dans le monde','Brûler moins de charbon, de pétrole et de gaz ; économiser l’énergie.'],['Chez nous','Protéger les mangroves et les récifs, construire loin du rivage.']])],
 [Q('Pourquoi le corail blanchit-il ?',['L’eau est trop chaude','Il a été peint','Il a trop froid']),Q('En quelle année a été signé l’accord de Paris ?',['2015','1853','1998'])],
 [R('Relie chaque action à son échelle.',[['Accord de Paris','Échelle mondiale'],['Protéger la mangrove de sa commune','Échelle locale']]),W('Propose une action, à l’échelle de ta commune, pour s’adapter au changement climatique.','Protéger ou replanter la mangrove, ne pas construire trop près du rivage, protéger le récif, économiser l’énergie et l’eau.')],
 'Coraux blanchis ; on agit à l’échelle mondiale (accord de Paris, 2015) et locale (mangroves, récifs, constructions loin du rivage).')],
f:{p:'En brûlant du charbon, du pétrole et du gaz, les humains réchauffent la [planète]. Les glaces fondent et le niveau de la [mer] monte. Les [atolls], comme Tuvalu, sont menacés. Il faut agir dans le monde entier et [s’adapter] chez nous.',w:['Lune','montagnes','déménager'],
 c:['La mer monte (l’eau se dilate, les glaces fondent) et menace les îles basses comme les atolls de Tuvalu ou de Kiribati ; les coraux blanchissent et l’on craint des cyclones plus violents.','Les îles du Pacifique sont les plus grands pollueurs du monde.','Le Pacifique se refroidit et gèle.'],
 r:'En brûlant charbon, pétrole et gaz, les humains renforcent l’effet de serre : la Terre se réchauffe. L’eau des océans se dilate et les glaces fondent : la mer est montée d’environ 20 cm depuis 1900. Les atolls (Tuvalu, Kiribati, îles Marshall) dépassent à peine la mer ; en 2023, Tuvalu a signé un traité avec l’Australie pour que jusqu’à 280 habitants par an puissent s’y installer. Les coraux blanchissent et l’on craint des cyclones plus violents. On agit à deux échelles : l’accord de Paris (2015) et, localement, la protection des mangroves et des récifs.'}});

E(11,{q:'Comment la Nouvelle-Calédonie est-elle reliée au monde, et pourquoi la mondialisation la touche-t-elle directement ?',
h:['Par son port, son aéroport et ses câbles ; elle vend du nickel et achète beaucoup au monde','Elle vit seule et ne commerce avec personne','Elle n’est reliée qu’à la France'],
pg:[
P('Vendre au monde',[I('vraquier2'),TB('Ce que vend la Nouvelle-Calédonie',['Produits','Part des exportations','Principaux clients'],[['Produits du nickel (minerai, ferronickel…)','environ 9 sur 10, en valeur','Chine (1er client), Japon, Corée du Sud'],['Autres produits (crevettes, poissons…)','une petite part','plusieurs pays']],'Tableau de l’atlas (chiffres arrondis).')],
 [Q('Quel est le premier produit vendu par la Nouvelle-Calédonie ?',['Le nickel','Le chocolat','Les voitures']),Q('Quel pays est son premier client ?',['La Chine','Le Brésil','La Suisse'])],
 [Q('Quelle part des exportations vient du nickel ?',['Environ 9 sur 10','Environ 1 sur 10','La moitié']),W('Pourquoi dit-on que la Nouvelle-Calédonie dépend d’un seul produit ?','Presque toutes ses ventes à l’étranger (environ 9 sur 10) sont des produits du nickel : si le nickel va mal, toute l’économie souffre.')],
 'Le nickel représente environ 9 exportations sur 10, vendues surtout en Asie (Chine, Japon, Corée du Sud).'),
P('Acheter au monde',X('Fiche : le caddie d’une famille calédonienne','Fiche de l’atlas (exemple simplifié).',"Dans le caddie : du riz et des pommes venus de loin, du lait en poudre, des biscuits.\nLa Nouvelle-Calédonie achète beaucoup à l'étranger : nourriture, carburant, voitures, machines, médicaments.\nSon premier fournisseur est la France, puis viennent la Chine, l'Australie, Singapour…\nTout arrive par bateau ou par avion, ce qui rend souvent les produits plus chers.","La Nouvelle-Calédonie achète beaucoup à l'étranger : nourriture, carburant, voitures, médicaments. Le premier fournisseur est la France, puis la Chine, l'Australie, Singapour. Tout arrive par bateau ou par avion."),
 [Q('Quel est le premier fournisseur de la Nouvelle-Calédonie ?',['La France','La Chine','Le Japon']),V('Les produits achetés à l’étranger arrivent par bateau ou par avion.',1)],
 [Q('Comment appelle-t-on les produits achetés à l’étranger ?',['Des importations','Des exportations','Des productions locales']),W('Pourquoi les produits importés coûtent-ils souvent plus cher en Nouvelle-Calédonie ?','Ils viennent de loin : il faut payer le transport par bateau ou par avion, les frais de port et de douane, et le marché est petit.')],
 'La Nouvelle-Calédonie importe beaucoup (nourriture, carburant, voitures…) : 1er fournisseur la France, puis la Chine, l’Australie, Singapour.'),
P('Les portes d’entrée',[I('noumeaport'),I('tontouta')],
 [R('Relie chaque porte d’entrée à ce qu’elle reçoit.',[['Port de Nouméa','Les conteneurs'],['La Tontouta','Les avions'],['Gondwana-1 et 2','Les données d’internet']]),V('Sans son port, la Nouvelle-Calédonie serait isolée.',1)],
 [Q('Comment appelle-t-on un lieu de contact entre un territoire et le reste du monde, comme un port ?',['Une interface','Une frontière fermée','Un désert humain']),W('Pourquoi le port de Nouméa, La Tontouta et les câbles Gondwana sont-ils vitaux ?','Ce sont les portes d’entrée du pays : par eux arrivent les marchandises, les voyageurs et les données d’internet ; sans eux, une île aussi lointaine serait coupée du monde.')],
 'Port de Nouméa (conteneurs), La Tontouta (avions), Gondwana-1 et 2 (internet) : les portes d’entrée du pays.'),
P('Un petit pays dans un grand monde',[M('Carte de l’atlas : la Nouvelle-Calédonie dans la mondialisation'),TB('Quand le monde bouge, la Nouvelle-Calédonie le sent',['Ce qui se passe ailleurs','Effet ici'],[['Le prix mondial du nickel baisse','Les usines perdent de l’argent, des emplois sont menacés'],['L’Indonésie produit beaucoup de nickel bon marché','Le nickel calédonien a du mal à se vendre'],['Le prix du pétrole monte','Carburant, transport et électricité coûtent plus cher'],['Une crise frappe l’Asie','Les clients achètent moins de nickel']],'Tableau de l’atlas.')],
 [Q('Que se passe-t-il ici quand le prix du pétrole monte ?',['Le carburant et le transport coûtent plus cher','Il pleut davantage','Rien du tout']),V('Ce qui se passe à l’autre bout du monde peut avoir des effets en Nouvelle-Calédonie.',1)],
 [Q('Quel pays est le grand concurrent de la Nouvelle-Calédonie pour le nickel ?',['L’Indonésie','La Suisse','Le Canada']),W('« C’est cela, la mondialisation. » Explique avec un exemple du tableau.','Les pays sont reliés : par exemple, quand l’Indonésie produit beaucoup de nickel bon marché, le prix mondial baisse, et les usines calédoniennes perdent de l’argent et des emplois.')],
 'Prix du nickel, concurrence de l’Indonésie, prix du pétrole : des événements lointains ont des effets directs ici.')],
f:{p:'La Nouvelle-Calédonie vend surtout du [nickel], en grande partie en [Asie]. Elle achète beaucoup à l’étranger, d’abord à la [France]. Son port, son aéroport et ses câbles sont ses portes d’entrée : ce qui se passe dans le [monde] a des effets directs ici.',w:['café','Afrique','Brésil'],
 c:['Elle vend surtout du nickel à l’Asie et achète beaucoup, surtout à la France, grâce à son port, à La Tontouta et à ses câbles ; le prix du nickel, la concurrence de l’Indonésie ou le prix du pétrole la touchent donc directement.','Elle ne commerce avec personne : la mondialisation ne la concerne pas.','Elle vend surtout des voitures à l’Europe.'],
 r:'La Nouvelle-Calédonie vend surtout des produits du nickel (environ 9 exportations sur 10), en grande partie en Asie : la Chine est son premier client, devant le Japon et la Corée du Sud. Elle achète beaucoup à l’étranger (nourriture, carburant, voitures, médicaments), d’abord à la France puis à la Chine, à l’Australie et à Singapour. Le port de Nouméa, La Tontouta et les câbles Gondwana-1 et 2 sont ses interfaces avec le monde. C’est pourquoi le prix mondial du nickel, la concurrence de l’Indonésie ou le prix du pétrole ont des effets directs sur le pays.'}});

})();
